#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;
    int fish;

    Cat(string n, int f) : name(n), fish(f) {}
    void show() const;
};

void Cat::show() const {
    cout << name << " 有 " << fish << " 条" << endl;
}

int main() {
    Cat c1("{name}", {fish});
    c1.show();
    return 0;
}
